(* [comment removed for export] *)
Lemma coh_mem : forall A m m' h, WF A -> VMok A h -> Coh A m h ->
  (forall a : word, m' a <> None -> 0x1000 <= bv_unsigned a < alloc_ceiling ->
     ~ (IMG_LO <= bv_unsigned a < IMG_HI) -> m a <> None \/ dom A (bv_unsigned a)) ->
  Coh A m' h.
Proof.
